#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Ticket 43's closing run: M3's nested exit from ticket 17 and every M1, M2 and
# M3 checklist item (docs/testing/checklist.md), on the installed caminito-git.
# Run it from a terminal on the host desktop, with tools/dev-nested (not --bin)
# in a second terminal. The results are appended to the ticket's notes, for the
# Close M3 XWayland commit. They're saved as they're given, so a stopped run
# resumes where it left off.

TOTAL_STAGES=13

# A later milestone's closing run names its own ticket in TICKET (59).
TICKET="${TICKET:-$(dirname "$(realpath "$0")")/43-packaging-and-closing-m3.md}"
RESULTS=()   # "short name|pass or FAIL|note"
FAILED=()
STATE="${XDG_STATE_HOME:-$HOME/.local/state}/caminito"
PROGRESS="$STATE/43-closing-checks.progress"
ENV_BEFORE="$STATE/43-env-before"
SCRATCH_FILE="$STATE/43-scratch-config"
DEBUG_CALL=(busctl --user call org.mate.Caminito.Debug /org/mate/Caminito/Debug org.mate.Caminito.Debug)
ROOT_PROPS=(_NET_SUPPORTED _NET_NUMBER_OF_DESKTOPS _NET_DESKTOP_NAMES _NET_CURRENT_DESKTOP
  _NET_WORKAREA _GTK_WORKAREAS_D0)

# x11 CMD... starts an X11 client on the nested Xwayland, detached. GTK apps get
# their own session bus, so they can't hand off to an instance on the host's.
x11() {
  env -u WAYLAND_DISPLAY DISPLAY=":$NESTED_X" GDK_BACKEND=x11 \
    setsid dbus-run-session -- "$@" >/dev/null 2>&1 &
}
# native CMD... starts a Wayland client on the nested Caminito, detached.
native() {
  env -u DISPLAY WAYLAND_DISPLAY="$NESTED_WL" GDK_BACKEND=wayland \
    setsid dbus-run-session -- "$@" >/dev/null 2>&1 &
}
# show CMD... runs a command and shows it with its output, indented.
show() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@" 2>&1 | sed 's/^/    /' || true; }
# nx CMD... runs an X command against the nested Xwayland and shows its output.
nx() { show env DISPLAY=":$NESTED_X" "$@"; }
# nested_env prints the nested Caminito's bus and scratch config, as the checklist's does.
nested_env() {
  tr '\0' '\n' </proc/"$(pgrep -n -x caminito)"/environ |
    grep -E '^(DBUS_SESSION_BUS_ADDRESS|XDG_CONFIG_HOME)='
}
# nbus CMD... runs a command on the nested Caminito's session bus and shows its output.
nbus() { local vars; mapfile -t vars < <(nested_env || true); show env "${vars[@]}" "$@"; }
# x_window CLASS prints the id of the first nested X window whose instance is CLASS.
x_window() {
  env DISPLAY=":$NESTED_X" wmctrl -lx 2>/dev/null |
    awk -v c="$1" 'tolower($3) ~ "^" c "\\." {print $1; exit}'
  true
}
# ensure_x11 INSTANCE CMD... starts CMD on the nested Xwayland unless a window of
# INSTANCE is already open.
ensure_x11() { [[ -n $(x_window "$1") ]] || { shift; x11 "$@"; sleep 2; }; }
# ok "..." prints a check that passed.
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# read_nested asks for the line tools/dev-nested prints once Xwayland is ready.
read_nested() {
  local line
  while true; do
    printf '  %sPaste the line "dev-nested: WAYLAND_DISPLAY=… DISPLAY=:…":%s ' "$BOLD" "$RESET"
    read -r line || true
    if [[ $line =~ WAYLAND_DISPLAY=(wayland-[0-9]+)\ DISPLAY=:([0-9]+) ]]; then
      NESTED_WL=${BASH_REMATCH[1]}; NESTED_X=${BASH_REMATCH[2]}
      printf '  %s✓%s nested WAYLAND_DISPLAY=%s DISPLAY=:%s\n' "$GREEN" "$RESET" "$NESTED_WL" "$NESTED_X"
      return
    fi
    warn "that isn't the dev-nested line; try again"
  done
}

# result "Short name" records whether the check passed, with an optional note.
result() {
  local name="$1" verdict note=""
  if confirm "Did all of it work? ($name)"; then verdict=pass; else verdict=FAIL; FAILED+=("$name"); fi
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  RESULTS+=("$name|$verdict|$note")
  printf '%s|%s|%s\n' "$name" "$verdict" "$note" >> "$PROGRESS"
}

# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$STATE"
  [[ -s $PROGRESS ]] || return 0
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r name verdict _ <<< "$r"
      if [[ $verdict == FAIL ]]; then FAILED+=("$name"); fi
    done
  else
    : > "$PROGRESS"
    rm -f "$ENV_BEFORE" "$SCRATCH_FILE"
  fi
}

# done_already NAME... succeeds, and says so, when every named result is recorded.
done_already() {
  local name
  for name in "$@"; do
    printf '%s\n' "${RESULTS[@]}" | grep -q "^$(printf '%s' "$name" | sed 's/[][\\.*^$]/\\&/g')|" || return 1
  done
  say "Already recorded; skipping."
  sleep 1
}

# write_results appends the results to the ticket's notes.
write_results() {
  local r name verdict note line
  grep -q '^## Notes' "$TICKET" || printf '\n## Notes\n' >> "$TICKET"
  printf '\n- **Closing run by hand (%s), on %s:**\n' "$(date +%F)" "$(pacman -Q caminito-git)" >> "$TICKET"
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r name verdict note <<< "$r"
    line=$(printf '  - %s: %s.%s' "$name" "$verdict" "${note:+ $note}")
    # A resumed run's earlier results may be in the notes already.
    grep -qxF -- "$line" "$TICKET" || printf '%s\n' "$line" >> "$TICKET"
  done
  printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$TICKET"
}

banner "Ticket 43: closing M3 on the installed package"
load_progress

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before starting the nested Caminito"
say "Run this on the host desktop, not on a tty, from the checkout."
show pacman -Q caminito-git
[[ $(command -v caminito) == /usr/bin/caminito ]] || warn "caminito isn't the installed /usr/bin/caminito"
for tool in xterm xeyes wmctrl xprop xclip xwininfo foot pluma gtk3-demo dconf; do
  command -v "$tool" >/dev/null || warn "$tool is missing"
done
if [[ ! -s $ENV_BEFORE ]]; then
  say "Don't start Caminito yet. Saving the host's systemd environment first (M1)."
  systemctl --user show-environment | sort > "$ENV_BEFORE"
  printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$ENV_BEFORE"
fi
step "Now, in a second terminal, from the checkout, run:  tools/dev-nested"
step "No --bin: these checks are on the installed package."
step "Wait for its line  dev-nested: WAYLAND_DISPLAY=wayland-N DISPLAY=:M"
read_nested

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "M1: a nested run uses its private bus"
if ! done_already "A nested run uses its private bus"; then
show nested_env
show printenv DBUS_SESSION_BUS_ADDRESS
note "Expected: Caminito's DBUS_SESSION_BUS_ADDRESS is dbus-run-session's own bus,"
note "not the host's unix:path=/run/user/$(id -u)/bus shown second."
result "A nested run uses its private bus"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "M1: dconf goes to the scratch config"
if ! done_already "dconf goes to the scratch config, while running"; then
{ nested_env || true; } | sed -n 's/^XDG_CONFIG_HOME=//p' > "$SCRATCH_FILE"
nbus sh -c 'dconf write /org/caminito/checklist true; dconf read /org/caminito/checklist; ls "$XDG_CONFIG_HOME/dconf"'
show dconf read /org/caminito/checklist
note "Expected: the nested read prints true and ls lists user. The host read, second,"
note "prints nothing. Whether the scratch directory goes is checked once Caminito quits."
result "dconf goes to the scratch config, while running"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "M2: the debug interface answers on the nested bus"
if ! done_already "The debug interface answers on the nested bus"; then
say "Opening pluma on $NESTED_WL."
native pluma
pause "Press Enter once pluma has mapped"
nbus "${DEBUG_CALL[@]}" DumpState
note "Expected: pluma's window as ssd, with its frame extents and strip_scale 1."
nbus "${DEBUG_CALL[@]}" ToggleFrameDebug
step "It answers true, and pluma's frame gets red strip outlines, a blue resize"
step "border and a green title outline, labelled ×1."
pause "Press Enter to toggle it off"
nbus "${DEBUG_CALL[@]}" ToggleFrameDebug
step "It answers false, and the outlines go."
result "The debug interface answers on the nested bus"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "M2: a theme switch while windows are open"
if ! done_already "A theme switch while windows are open"; then
pgrep -f "^pluma$" >/dev/null || native pluma
say "Opening caja and gtk3-demo on $NESTED_WL beside pluma. pluma won't start a second"
say "instance, so caja is the second framed window."
native caja --no-desktop /tmp
native gtk3-demo
step "Maximise pluma, and leave caja at its size. gtk3-demo stays CSD."
pause "Press Enter once pluma is maximised"
for theme in BlackMATE HighContrast TraditionalOk NoSuchTheme Menta; do
  nbus gsettings set org.mate.Marco.general theme "$theme"
  sleep 2
  nbus "${DEBUG_CALL[@]}" DumpState
  step "pluma's and caja's frames are now $theme's, with no window unmapped."
  pause "Press Enter for the next theme"
done
note "Expected: caja's client area kept its size, the maximised pluma"
note "and its frame still fill the output, and frame_extents followed the theme."
note "NoSuchTheme gave the built-in theme, with one \"can't load the Marco theme NoSuchTheme\""
note "line in the dev-nested terminal. On Menta the buttons still prelight, press and act."
result "A theme switch while windows are open"
say "Close pluma, caja and gtk3-demo."
pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "M3: X11 apps map, get frames, take focus and move"
if ! done_already "X11 apps map, get frames, take focus and move"; then
say "Opening xterm, xeyes and gtk3-demo's Application Class demo on :$NESTED_X."
x11 xterm
x11 xeyes
x11 gtk3-demo --run=application_demo
step "All three map with Menta frames."
step "Click each in turn: it takes focus, its frame going active and the others'"
step "inactive."
step "Drag each by its titlebar: it moves."
step "Type in xterm and in the demo's text area: the text goes to each."
note "xeyes follows the pointer only over X windows; that's rootless Xwayland (46)."
result "X11 apps map, get frames, take focus and move"
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "M3: menus and tooltips in the override-redirect layer"
if ! done_already "Menus and tooltips sit in the override-redirect layer"; then
ensure_x11 gtk3-demo-application gtk3-demo --run=application_demo
say "Opening gtk3-demo's Builder demo on :$NESTED_X too."
x11 gtk3-demo --run=builder
step "Application Class demo: click the Preferences menu. It opens above its window."
step "Down, then Right on Color, opens the submenu, also on top. Escape backs out."
step "Click outside the menu: it closes, and typing goes to the window again."
step "Builder demo: hover the toolbar's New button. \"Create a new file\" shows above"
step "both demo windows, and goes when the pointer leaves the button."
step "xterm: Ctrl+left-click opens its Main Options menu above it. Escape closes it."
result "Menus and tooltips sit in the override-redirect layer"
say "Close the Builder demo; keep xterm, xeyes and the Application Class demo."
pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "M3: _NET_FRAME_EXTENTS and _NET_WORKAREA"
if ! done_already "_NET_FRAME_EXTENTS and _NET_WORKAREA are right"; then
ensure_x11 xterm xterm
ensure_x11 xeyes xeyes
ensure_x11 gtk3-demo-application gtk3-demo --run=application_demo
for class in xterm xeyes gtk3-demo-application; do
  id=$(x_window "$class")
  say "$class ($id):"
  if [[ -n $id ]]; then nx xprop -id "$id" _NET_FRAME_EXTENTS; else warn "no $class window found"; fi
done
note "Expected: 1, 1, 31, 1 (left, right, top, bottom), the Menta frame's, for each."
nx xprop -root _NET_NUMBER_OF_DESKTOPS _NET_WORKAREA _GTK_WORKAREAS_D0
nx sh -c 'xwininfo -root | grep -E "Width|Height"'
note "Expected: _NET_WORKAREA is 0, 0, width, height of the root, once per desktop (4),"
note "and _GTK_WORKAREAS_D0 the same rectangle. No struts exist until M5."
result "_NET_FRAME_EXTENTS and _NET_WORKAREA are right"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "M3: an X11 app's copy and paste to and from a native app"
if ! done_already "An X11 app's copy and paste to and from a native app"; then
say "Opening foot on $NESTED_WL, and an xterm with foot's clipboard keys on :$NESTED_X."
native foot
x11 xterm -T clipboard -xrm 'XTerm*VT100.translations: #override Ctrl Shift <Key>C: copy-selection(CLIPBOARD)\nCtrl Shift <Key>V: insert-selection(CLIPBOARD)'
step "Clipboard: select text in one, Ctrl+Shift+C, click the other, Ctrl+Shift+V."
step "Both ways, xterm (titled \"clipboard\") → foot and foot → xterm."
step "Primary selection: select text in one, middle-click in the other. Both ways."
step "Then copy something new in foot (Ctrl+Shift+C) and leave foot focused."
pause "Press Enter once foot is focused with new text copied"
nx xclip -o -selection clipboard
note "Expected: the text pastes unchanged every way. xclip prints what xterm last copied,"
note "not foot's new text: X only gets a Wayland selection once an X window is focused (37)."
result "An X11 app's copy and paste to and from a native app"
say "Close foot and the \"clipboard\" xterm."
pause
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "M3: killing Xwayland brings it back"
if ! done_already "Killing Xwayland brings it back with the root properties republished"; then
ensure_x11 xterm xterm
before=$(env DISPLAY=":$NESTED_X" xprop -root "${ROOT_PROPS[@]}" 2>&1 || true)
say "The root properties now:"
printf '%s\n' "$before" | sed 's/^/    /'
XW_PID=$(ps -eo pid=,args= | awk -v d=":$NESTED_X" '$2 ~ /Xwayland$/ && $3 == d {print $1; exit}')
if [[ -z $XW_PID ]]; then
  warn "couldn't find the nested Xwayland on :$NESTED_X; find it with  ps -eo pid,args | grep Xwayland"
  printf '  %sIts pid:%s ' "$BOLD" "$RESET"
  read -r XW_PID || true
fi
say "The nested Xwayland is pid $XW_PID:"
ps -o pid=,args= -p "$XW_PID" | sed 's/^/    /'
if confirm "Kill it (SIGKILL)?"; then
  old_x=$NESTED_X
  kill -9 "$XW_PID"
  step "Every X window disappears from Caminito's output, and the dev-nested terminal"
  step "logs the restart, then a new  dev-nested: … DISPLAY=:$old_x  line."
  read_nested
  [[ $NESTED_X == "$old_x" ]] || warn "Xwayland came back on :$NESTED_X, not :$old_x"
  after=$(env DISPLAY=":$NESTED_X" xprop -root "${ROOT_PROPS[@]}" 2>&1 || true)
  if [[ $before == "$after" ]]; then
    ok "the root properties are republished unchanged"
  else
    warn "the root properties differ after the restart:"
    diff <(printf '%s\n' "$before") <(printf '%s\n' "$after") | sed 's/^/    /' || true
  fi
  x11 xterm
  step "A new xterm maps on the same DISPLAY, with a Menta frame, and takes typing."
  result "Killing Xwayland brings it back with the root properties republished"
else
  SKIPPED+=("the Xwayland restart check")
fi
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "M1: quit Caminito, and check what it left"
if ! done_already "dconf goes to the scratch config, after exit" \
    "The host desktop's systemd environment is untouched"; then
step "Quit Caminito: Ctrl+C in the dev-nested terminal, and wait for it to exit."
pause "Press Enter once dev-nested has exited"
fi
if ! done_already "dconf goes to the scratch config, after exit"; then
scratch=$(cat "$SCRATCH_FILE" 2>/dev/null || true)
if [[ -z $scratch ]]; then
  warn "the scratch XDG_CONFIG_HOME wasn't saved in stage 3"
elif [[ -e $scratch ]]; then
  warn "$scratch is still there"
else
  ok "$scratch is gone"
fi
show dconf read /org/caminito/checklist
note "Expected: the host read prints nothing."
result "dconf goes to the scratch config, after exit"
fi
if ! done_already "The host desktop's systemd environment is untouched"; then
if env_diff=$(diff "$ENV_BEFORE" <(systemctl --user show-environment | sort)); then
  ok "the host systemd environment is the same as before the run"
else
  warn "the host systemd environment changed:"
  printf '%s\n' "$env_diff" | sed 's/^/    /'
fi
result "The host desktop's systemd environment is untouched"
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "M2: frames at an output scale of 2"
if ! done_already "Frames at an output scale of 2 in a nested run"; then
step "Start it again at scale 2:  tools/dev-nested --scale 2"
read_nested
native pluma
pause "Press Enter once pluma has mapped"
nbus "${DEBUG_CALL[@]}" DumpState
note "Expected: the output at scale 2, pluma's window ssd with strip_scale 2, and the"
note "same frame_extents as at scale 1."
nbus "${DEBUG_CALL[@]}" ToggleFrameDebug
step "Frame debug labels the frame ×2, and its outlines sit on the frame's edges."
step "The title and button icons are as sharp as pluma's content, not blurred or doubled."
step "Hover, press and release each titlebar button: they prelight, press and act."
step "Drag the titlebar, and resize from an edge and a corner, where the outlines say."
result "Frames at an output scale of 2 in a nested run"
step "Quit Caminito (Ctrl+C in the dev-nested terminal)."
pause
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Record the results"
for r in "${RESULTS[@]}"; do
  IFS='|' read -r name verdict note <<< "$r"
  say "$verdict  $name${note:+ ($note)}"
done
if confirm "Write these to the ticket's notes?"; then
  write_results
  rm -f "$PROGRESS" "$ENV_BEFORE" "$SCRATCH_FILE"
  (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure: ${FAILED[*]}")
else
  SKIPPED+=("recording the results in ticket 43 (they stay in $PROGRESS)")
fi
pause

finish
